#!/usr/bin/env bash
# cx-hook-input.sh — JSON parsing helpers for hook scripts.
# Source AFTER CX_PYTHON3 and HOOK_INPUT are set.

# Extract a field from $HOOK_INPUT (hook JSON payload).
# Usage: SESSION_ID=$(_cx_hook_field session_id unknown)
_cx_hook_field() {
    local field="$1" default="${2:-}"
    echo "$HOOK_INPUT" | "$CX_PYTHON3" -c \
        "import json,sys; print(json.load(sys.stdin).get('${field}','${default}'
))" 2>/dev/null                                                                 }

# Extract a field from a conversation JSON file.
# Usage: TITLE=$(_cx_conv_field "$_conv_file" title)
_cx_conv_field() {
    local file="$1" field="$2"
    [[ -z "$file" ]] && return
    "$CX_PYTHON3" -c \
        "import json,sys; print(json.load(open(sys.argv[1])).get('${field}',''))
" \                                                                                     "$file" 2>/dev/null
}

